"""Reviewed learning tasks for the remaining PDF books (17–27).
Run from the project root; pass the PDF directory as an optional first argument.
Existing course and survey content is preserved verbatim.
"""
import json,re,random,hashlib,sys,importlib.util
from pathlib import Path
from pypdf import PdfReader
DATA=Path('src/data')
PDF_ROOT=Path(sys.argv[1]) if len(sys.argv)>1 else Path.home()/'Downloads'
spec=importlib.util.spec_from_file_location('pdf_readings',Path(__file__).with_name('extract-learning-readings.py'))
reader=importlib.util.module_from_spec(spec);spec.loader.exec_module(reader);reader.source_root=PDF_ROOT
BOOKS={}
for number in range(17,28):
    file=next(PDF_ROOT.glob(f'{number:02}_*.pdf'))
    BOOKS[file.name]=reader.extract_book(file.name)
NEW=[]
def q(prompt,correct,wrong,explanation):
    wrong=wrong.split(' ¦ ')
    assert len(wrong)==3 and len(set([correct]+wrong))==4,prompt
    return dict(kind='choice',prompt=prompt,options=[correct]+wrong,correct=0,explanation=explanation)
def o(prompt,answer,code,explanation):
    return dict(kind='output',prompt=prompt,answers=[answer],code=code,explanation=explanation)
def b(chapters,title,first,second):return dict(chapters=chapters,title=title,questions=[first,second])
def add(number,id,title,description,direction,symbol,color,blocks):
    filename=next(f for f in BOOKS if f.startswith(f'{number:02}_'))
    NEW.append(dict(number=number,id=id,title=title,description=description,direction=direction,symbol=symbol,color=color,blocks=blocks,source=filename))

