def write_json(path,value):path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def intro(sections):
    values=[p['text'] for section in sections for p in section['content'] if p['kind']=='paragraph']
    assert values,sections[0]['title']
    values=values[:3]
    return values

def main():
    catalog=json.loads((DATA/'learning-catalog.json').read_text(encoding='utf-8'))
    directions=json.loads((DATA/'learning-directions.json').read_text(encoding='utf-8'))
    readings=json.loads((DATA/'learning-readings.json').read_text(encoding='utf-8'))
    survey=json.loads((DATA/'questions.json').read_text(encoding='utf-8'))
    for item in [
        dict(id='quality',title='Тестирование и качество',description='Тест-дизайн, автотесты .NET и исследования производительности.'),
        dict(id='operations',title='Инструменты и эксплуатация',description='Git, Linux, контейнеры, доставка изменений и наблюдаемость.'),
        dict(id='architecture',title='Архитектура и надёжность',description='Границы модулей, распределённые системы и системный дизайн.')
    ]:
        if not any(d['id']==item['id'] for d in directions):directions.append(item)
    for spec in NEW:
        source=spec['source'];chapters=BOOKS[source]
        covered={str(n) for block in spec['blocks'] for n in block['chapters']}
        assert covered==set(chapters),(source,set(chapters)-covered,covered-set(chapters))
        lessons=[];reading={};open_questions=[]
        for index,block in enumerate(spec['blocks'],1):
            id=f'unit-{index:02}';sections=[chapters[str(n)] for n in block['chapters']]
            pages=[int(p) for s in sections for p in re.findall(r'\d+',s['pages'])]
            page_range=str(min(pages)) if min(pages)==max(pages) else f'{min(pages)}–{max(pages)}'
            tasks=[]
            for number,task in enumerate(block['questions'],1):
                task=dict(task);task['id']=f"pdf{spec['number']}-{id}-{number}"
                if task['kind']=='choice':
                    order=list(range(4));random.Random(int(hashlib.sha256(task['id'].encode()).hexdigest(),16)).shuffle(order)
                    task['options']=[task['options'][i] for i in order];task['correct']=order.index(0)
                    open_questions.append(dict(id=f"open-{spec['id']}-{id}-{number}",text=task['prompt']+' Обоснуйте ответ.',block=block['title'],source=f'{source}, стр. {page_range}'))
                tasks.append(task)
            lessons.append(dict(id=id,title=block['title'],source=source,pages=page_range,theory=intro(sections),readingChapters=block['chapters'],questions=tasks))
            reading[id]=sections
        id=spec['id'];file=id+'-course.json';pages=len(PdfReader(PDF_ROOT/source).pages)
        write_json(DATA/file,dict(id=id,version=1,title=spec['title'],description=spec['description'],source=source,lessons=lessons))
        metadata=dict(id=id,file=file,direction=spec['direction'],scope='dotnet' if spec['number']==18 else 'universal',pageCount=pages,sources=[dict(file=source,pages=pages)],symbol=spec['symbol'],color=spec['color'],topicIds=[id])
        match=next((i for i,c in enumerate(catalog) if c['id']==id),None)
        if match is None:catalog.append(metadata)
        else:catalog[match]=metadata
        readings[id]=reading
        old=next((i for i,t in enumerate(survey['topics']) if t['id']==id),None)
        topic=dict(id=id,number=survey['topics'][old]['number'] if old is not None else len(survey['topics'])+1,title=spec['title'],symbol=spec['symbol'],color=spec['color'],description=spec['description'],questions=open_questions)
        if old is None:survey['topics'].append(topic)
        else:survey['topics'][old]=topic
        print(id,len(lessons),'blocks',len(open_questions),'open questions')
    survey['revision']=max(4,survey.get('revision',0))
    write_json(DATA/'learning-catalog.json',catalog);write_json(DATA/'learning-directions.json',directions);write_json(DATA/'learning-readings.json',readings);write_json(DATA/'questions.json',survey)
    print('Total:',len(catalog),'courses;',len(survey['topics']),'topics;',sum(len(t['questions']) for t in survey['topics']),'open questions')

if __name__=='__main__':main()
